INSERT INTO bo_project (id, edition, title, short_desc, cost_pln, lon, lat, district, categories, is_aed_related, url) VALUES
(8341,'na rok 2019','Zarybianie Kanałku w Parku Kępa Potocka','Pomysł zakłada zarybienie kanałku narybkiem (płoć, lin, karaś pospolity).',3000.0,NULL,NULL,'Żoliborz',ARRAY['ochrona środowiska','przestrzeń publiczna','zieleń miejska']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8341'),
(8345,'na rok 2019','Rewitalizacja terenu pomiędzy ulicą Redutową a Elekcyjną ','Rewitalizacja terenu przyległego do chodnika pomiędzy ul. Redutową i Elekcyjną - przedłużenie ul. Pustola. Remont chodników oraz wymiana oświetlenia.',491160.0,20.943718070424,52.2333167572416,'Wola',ARRAY['komunikacja publiczna i drogi','przestrzeń publiczna','zieleń miejska']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8345'),
(8349,'na rok 2019','Dzikie rośliny jadalne i lecznicze - warsztaty w terenie, nauka rozpoznawania i zbierania ziół, przypraw','5 wycieczek poprowadzonych przez doświadczonego etnobotanika, po terenie Mazowieckiego Parku Krajobrazowego (i nie tylko), podczas których uczestnicy nabywają umiejętności rozpoznawania, i zbierania ziół, przypraw i innych naturalnych produktów roślinnych.',3000.0,NULL,NULL,'Wawer',ARRAY['edukacja','ochrona środowiska','zdrowie']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8349'),
(8353,'na rok 2019','Zielone Szmulki','Urządzenie od podstaw oraz planowo zieleni osiedlowej towarzyszącej zabudowie wielorodzinnej. Zapewnienie estetycznego i cichego zieleńca dla okolicznych mieszkańców.',125051.4,NULL,NULL,'Praga-Północ',ARRAY['ochrona środowiska','przestrzeń publiczna','zieleń miejska']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8353'),
(8359,'na rok 2019','Budki dla ptaków śpiewających i nietoperzy - pogromców komarów','Zakup 50 sztuk budek lęgowych i 2 karmików i zawieszenie ich w Lesie Matki Mojej (gdzie brak jakichkolwiek budek) oraz 40 sztuk budek dla nietoperzy - 30 można zawiesić w okolicach Rezerwatu im. Króla Jana Sobieskiego, zaś 10 przy oczku wodnym, przy siedzibie Lasów Miejskich.',7100.0,21.1441154417116,52.2314541652558,'Wawer',ARRAY['ochrona środowiska','zdrowie']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8359'),
(8371,'na rok 2019','Spotkania sąsiedzkie wolskich Seniorów','Mieszkańcy osiedla "Mszczonowska" to w większości Seniorzy. Świetnym pomysłem byłaby organizacja cyklicznych spotkań, które aktywizowałyby Seniorów i służyły integracji społeczności lokalnej. Starsi ludzie potrzebują wsparcia i akceptacji, a także motywacji. Na spotkaniach mogliby porozmawiać o swoich problemach i wspólnych sprawach, a także wspólnie zmobilizować się do działania.',13000.0,NULL,NULL,'Wola',ARRAY['kultura']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8371'),
(8375,'na rok 2019','"Potyczki SLAMowe" - warsztaty i turniej','Czym jest slam?, Jak pisać teksty na slam?, W jaki sposób zaprezentować utwór przed publicznością?, Jak wygrać slam?! - odpowiedzi na te, i inne pytania znajdziesz na warsztatach z kreatywnego pisania tekstów, improwizacji i występowania przed publicznością. Będzie to doskonała okazja do zapoznania się z energią sceniczną i sztuką żywego słowa.',3700.0,NULL,NULL,'Wola',ARRAY['edukacja','kultura']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8375'),
(8378,'na rok 2019','Komiksy dla Biblioteki Komiksowo (przy al. Solidarności 90) ','Wychodząc naprzeciw sugestiom czytelników Biblioteka dla Dzieci i Młodzieży nr 21 zmieniła się w niezwykle kolorową Bibliotekę Komiksową. Zmiana spotkała się z dużą życzliwością społeczności lokalnej. Zakup nowych komiksowych tytułów zapewni ich amatorom bogaty wybór w jednym miejscu, których wypożyczenia odbywać się będą nieodpłatnie.',12500.0,20.987491607666,52.2401111720267,'Wola',ARRAY['edukacja','kultura']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8378'),
(8386,'na rok 2019','Kulturalne Podwórka','Integracja mieszkańców dzielnicy Ursus na kameralnych imprezach zwanych "Kulturalne Podwórka", połączonych z koncertami na trawie, spektaklami, grami planszowymi na kocach, zajęciami plastycznymi, grami podwórkowymi czy warsztatami ruchowymi, dyskusjami, spotkaniami międzypokoleniowymi. Zależy nam na tworzeniu małych przestrzeni lokalnych, gdzie czujemy się dobrze, mamy możliwość poznać się i spędzić czas z sąsiadami.',13200.0,NULL,NULL,'Ursus',ARRAY['edukacja','kultura','przestrzeń publiczna']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8386'),
(8391,'na rok 2019','Estradowa Radość - muzyka w kulturotece dla dzieci i dorosłych','Projekt obejmuje zorganizowanie 10 koncertów muzycznych dla dorosłych (jazz, blues, rock, poezja śpiewana itd. o zróżnicowanej tematyce) oraz 10 koncertów muzycznych dla dzieci (edukacyjne z możliwością poznawania instrumentów. Będą organizowane dwa koncerty miesięcznie. 1 dla dzieci i 1 dla dorosłych, także z muzyką klasyczną. ',48000.0,NULL,NULL,'Wawer',ARRAY['edukacja','kultura']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8391'),
(8399,'na rok 2019','Wymiana nawierzchni oraz zagospodarowanie boiska przy SP 382 przy ulicy Konińskiej 2 w Warszawie','Wymiana sztucznej nawierzchni boiska do gry przy SP 382, przy ul. Konińskiej 2.',435482.0,NULL,NULL,'Ursus',ARRAY['edukacja','sport']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8399'),
(8404,'na rok 2019','Zakup specjalistycznego sprzętu do diagnozy i terapii dzieci i młodzieży z trudnościami w koncentracji','Zakup specjalistycznego sprzętu stosowanego w metodzie Warnkego umożliwi kompleksową diagnozę i terapię dzieci z trudnościami w koncentracji uwagi,czytaniu, pisaniu oraz mówieniu. Z diagnozy i terapii będą mogły uczestniczyć dzieci od 5 roku życia (na podstawie opinii lub orzeczenia) na terenie PPP nr 17.
Zapisy na zajęcia będą odbywać się za pośrednictwem jednostek organizacyjnych.',22960.0,NULL,NULL,'Wawer',ARRAY['edukacja','zdrowie']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8404'),
(8410,'na rok 2019','Poetycka Radość- Gałczyński, Tuwim, Twardowski- inaczej','Projekt obejmuje cykl koncertów poezji śpiewanej, oraz prelekcji słowno/ muzycznych twórców tj. Konstanty Ildefons Gałczyński, Julian Tuwim, Jan Twardowski, Edward Stachura, Bolesław Leśmian.',38250.0,21.1841640467173,52.184415238369,'Wawer',ARRAY['edukacja','kultura']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8410'),
(8413,'na rok 2019','Zieleń na Walerego Sławka 3/5','Zagospodarowanie zieleni na trawniku przylegającym do nieruchomości Wspólnoty Mieszkaniowej Walerego Sławka 3/5 od strony ul. Walerego Sławka oraz zagospodarowanie zieleni na terenie podwórza pomiędzy wskazaną wyżej nieruchomością a nieruchomościami Wspólnot Mieszkaniowych, znajdujących się przy ul. Marcina Szancera.',57138.0,NULL,NULL,'Ursus',ARRAY['zieleń miejska']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8413'),
(8416,'na rok 2019','Huśtawka rodzinna','Projekt dotyczy zakupienia dwóch huśtawek rodzinnych (rodzic + dziecko). Huśtawki posiadać będą stosowne atesty i certyfikaty.',9800.0,21.1529409885406,52.2404359842864,'Wawer',ARRAY['przestrzeń publiczna','sport','zdrowie']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8416'),
(8419,'na rok 2019','Naturalny, przyjazny przyrodzie trawnik w Parku Szczęśliwickim','Projekt polega na odnowieniu (renowacji) trawników w parku - na łącznej powierzchni 5 arów oraz  na zmianie zasad koszenia parkowych trawników w obrębie skarp - tak aby stały się one przyjazne przyrodzie i dawały schronienie bytującym w trawie zwierzętom. Tym samym zostanie zwiększona różnorodność i estetyka zieleni parkowej.',7500.0,20.9601974487305,52.2060592355058,'Ochota',ARRAY['ochrona środowiska','zieleń miejska']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8419'),
(8420,'na rok 2019','Kino za regałem - program literacko/filmowy dla dzieci','Program obejmuje cykl spotkań dla dzieci, w czasie których bajki, baśnie i fr. książek z  kanonu literatury dziecięcej, a po czytaniu nastąpi projekcja filmowa - adaptacja czytanej literatury.',8000.0,21.1842970832367,52.1845783742959,'Wawer',ARRAY['edukacja','kultura']::text[],false,'http://bo.um.warszawa.pl/processes/na-rok-2019/f/5/projects/8420'),
